// Job reference attachments are stored per job in this browser using IndexedDB.
const labels={process:'Processes',setup:'Past setups',engineering:'Engineering',model:'3D files'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let dbPromise,urls=[],lastFocus,job,category='process';
function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('tps-job-references',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'}).createIndex('job','job');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function records(){const d=await db();return new Promise((resolve,reject)=>{const r=d.transaction('files').objectStore('files').index('job').getAll(job.id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function save(record){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('files','readwrite');t.objectStore('files').put(record);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
function cleanup(){urls.forEach(URL.revokeObjectURL);urls=[]}
function blobURL(blob){const u=URL.createObjectURL(blob);urls.push(u);return u}
function close(){document.querySelector('#job-reference-drawer')?.close();cleanup();lastFocus?.focus()}
export function openJobDrawer(selected){job=selected;lastFocus=document.activeElement;category='process';let dialog=document.querySelector('#job-reference-drawer');if(!dialog){dialog=document.createElement('dialog');dialog.id='job-reference-drawer';dialog.className='reference-drawer';document.body.append(dialog);dialog.addEventListener('cancel',cleanup);dialog.addEventListener('click',e=>{if(e.target===dialog)close()})}dialog.innerHTML=`<div class="drawer-header"><div><div class="eyebrow">EMPLOYEE JOB REFERENCES</div><h2>Job details</h2><p>#${escape(job.id)} · ${escape(job.title)}<br>${escape(job.part)} · Rev ${escape(job.revision)}</p></div><button id="drawer-close" aria-label="Close job details">←</button></div><div class="drawer-tabs" role="tablist">${Object.entries(labels).map(([k,v])=>`<button role="tab" data-reference-tab="${k}" aria-selected="${k===category}">${v}</button>`).join('')}</div><div id="drawer-content" class="drawer-content"></div><div class="drawer-foot">References are saved for this job on this browser. Shared document storage will be connected separately.</div>`;dialog.querySelector('#drawer-close').onclick=close;dialog.querySelectorAll('[data-reference-tab]').forEach(b=>b.onclick=()=>{category=b.dataset.referenceTab;dialog.querySelectorAll('[role=tab]').forEach(t=>t.setAttribute('aria-selected',t===b));show()});dialog.showModal();show();dialog.querySelector('#drawer-close').focus()}
async function show(){cleanup();const content=document.querySelector('#drawer-content');content.innerHTML='<p>Loading references…</p>';try{const all=await records(),files=all.filter(f=>f.category===category);const descriptions={process:'Shop ISO procedures and job-specific coded notes.',setup:'Previous fixture arrangements and setup photos for this job.',engineering:'Engineering reference images and improvement guidance.',model:'Upload an STL model to rotate and inspect its shape.'};content.innerHTML=`<h3>${labels[category]}</h3><p class="subtitle">${descriptions[category]}</p>${category==='process'?`<label class="reference-label" for="coded-notes">CODED NOTES / PROCESS GUIDANCE</label><textarea id="coded-notes" rows="5" placeholder="Add procedure references and coded notes, e.g. procedure ID, revision, and instruction…"></textarea><div class="reference-note-action"><button id="save-coded-notes" class="primary">Save notes</button><span id="reference-status" role="status"></span></div>`:''}<label class="reference-upload">＋ Add ${category==='model'?'3D file':category==='process'?'procedure file':'images'}<input id="reference-files" type="file" multiple accept="${category==='model'?'.stl':category==='process'?'.pdf,.txt':'image/*'}"></label><div id="reference-list">${files.length?'':'<div class="reference-empty">No '+labels[category].toLowerCase()+' added to this job yet.</div>'}</div><p id="reference-error" role="alert" class="scan-error"></p>`;
if(category==='process'){const note=all.find(f=>f.category==='notes');content.querySelector('textarea').value=note?.text||'';content.querySelector('#save-coded-notes').onclick=async()=>{try{await save({id:job.id+'-notes',job:job.id,category:'notes',text:content.querySelector('textarea').value});content.querySelector('#reference-status').textContent='Saved on this browser'}catch{content.querySelector('#reference-status').textContent='Could not save notes'}}}
const list=content.querySelector('#reference-list');for(const f of files){const card=document.createElement('article');card.className='reference-card';const url=blobURL(f.blob);card.innerHTML=`<div class="reference-card-header"><strong>${escape(f.name)}</strong><a href="${url}" download="${escape(f.name)}">Download ↗</a></div>`;if(f.type.startsWith('image/')){const img=document.createElement('img');img.src=url;img.alt=f.name;card.append(img)}else if(f.name.toLowerCase().endsWith('.stl')){const canvas=document.createElement('canvas');canvas.width=700;canvas.height=400;canvas.setAttribute('aria-label','Interactive 3D STL preview. Drag to rotate.');card.append(canvas);const hint=document.createElement('p');hint.className='subtitle';hint.textContent='Drag to rotate · scroll to zoom';card.append(hint);try{drawSTL(canvas,await f.blob.arrayBuffer())}catch{hint.textContent='Unable to preview this STL. Download the file to inspect it.'}}else if(f.type==='application/pdf'){const frame=document.createElement('iframe');frame.src=url;frame.title=f.name;card.append(frame)}else if(f.name.toLowerCase().endsWith('.txt')){const pre=document.createElement('pre');pre.textContent=await f.blob.text();card.append(pre)}list.append(card)}
content.querySelector('#reference-files').onchange=async e=>{try{for(const f of e.target.files){if(f.size>20*1024*1024)throw Error('Choose files smaller than 20 MB.');const valid=category==='model'?/\.stl$/i.test(f.name):category==='process'?/\.(pdf|txt)$/i.test(f.name):f.type.startsWith('image/');if(!valid)throw Error('This file type is not supported in this section.');await save({id:crypto.randomUUID(),job:job.id,category,name:f.name,type:f.type,blob:f})}await show()}catch(err){content.querySelector('#reference-error').textContent=err.message}};
}catch{content.innerHTML='<p class="scan-error">References could not be loaded. Browser storage may be unavailable.</p>'}}
function drawSTL(canvas,buffer){let points=[];const view=new DataView(buffer);if(buffer.byteLength>=84&&84+view.getUint32(80,true)*50===buffer.byteLength){const count=view.getUint32(80,true);if(count>100000)throw Error('Model too large');for(let i=0;i<count;i++)for(let v=0;v<3;v++){const n=84+i*50+12+v*12;points.push([view.getFloat32(n,true),view.getFloat32(n+4,true),view.getFloat32(n+8,true)])}}else{const text=new TextDecoder().decode(buffer);for(const m of text.matchAll(/vertex\s+([-+\deE.]+)\s+([-+\deE.]+)\s+([-+\deE.]+)/g))points.push(m.slice(1).map(Number))}if(!points.length||points.length>300000||points.some(p=>p.some(v=>!Number.isFinite(v))))throw Error('Invalid STL');let min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity];points.forEach(p=>p.forEach((v,i)=>{min[i]=Math.min(min[i],v);max[i]=Math.max(max[i],v)}));const center=min.map((v,i)=>(v+max[i])/2),size=Math.max(...max.map((v,i)=>v-min[i]))||1;points=points.map(p=>p.map((v,i)=>(v-center[i])/size));let yaw=.6,pitch=-.4,zoom=270,last;const ctx=canvas.getContext('2d');function render(){ctx.fillStyle='#f1f5f9';ctx.fillRect(0,0,700,400);ctx.strokeStyle='#248cb7';ctx.lineWidth=.65;const project=p=>{const x=p[0]*Math.cos(yaw)+p[2]*Math.sin(yaw),z=-p[0]*Math.sin(yaw)+p[2]*Math.cos(yaw),y=p[1]*Math.cos(pitch)-z*Math.sin(pitch);return[350+x*zoom,200-y*zoom]};for(let i=0;i<points.length-2;i+=3){ctx.beginPath();const a=project(points[i]);ctx.moveTo(...a);ctx.lineTo(...project(points[i+1]));ctx.lineTo(...project(points[i+2]));ctx.closePath();ctx.stroke()}}canvas.onpointerdown=e=>{last=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!last)return;yaw+=(e.clientX-last[0])*.01;pitch+=(e.clientY-last[1])*.01;last=[e.clientX,e.clientY];render()};canvas.onpointerup=canvas.onpointercancel=()=>last=null;canvas.onwheel=e=>{e.preventDefault();zoom=Math.max(50,Math.min(1000,zoom-e.deltaY));render()};render()}
